import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long number = scanner.nextLong();

        long[] base = new long[19];
        base[0] = 1;
        for (int i = 1; i <= 18; ++i) {
            base[i] = base[i - 1] * 10;
        }

        long[] cumulative = new long[19];
        cumulative[0] = 0;
        for (int i = 1; i <= 18; ++i) {
            cumulative[i] = cumulative[i - 1] + base[i];
        }

        int max_index = 1;
        while (max_index <= 18 && cumulative[max_index] <= number) {
            ++max_index;
        }
        --max_index;

        int min_moves = Integer.MAX_VALUE;

        class Recurse {
            void recurseSearch(int idx, long val, int total) {
                if (val == 0) {
                    if (total < min_moves) {
                        min_moves = total;
                    }
                    return;
                }
                if (idx == 0) return;
                long b = base[idx];
                int i;
                for (i = -10; i * b <= val; ++i);
                recurseSearch(idx - 1, val - (i - 1) * b, total + Math.abs(i - 1) * (idx + 1));
                recurseSearch(idx - 1, val - i * b, total + Math.abs(i) * (idx + 1));
            }
        }

        new Recurse().recurseSearch(max_index, number, 0);
        System.out.println(min_moves);
        scanner.close();
    }
}
